baseCss:
.aha-features{
  container:aha-features / inline-size;
  background:var(--aha-white);
  color:var(--aha-text-default);
  font-family:var(--aha-font-product);
}
.aha-features *{box-sizing:border-box}
:where(.aha-features) :is(h2,h3,p,ul,ol,figure){margin:0;padding:0}
:where(.aha-features) :is(ul,ol){list-style:none}
.aha-features__inner{max-width:1280px;margin:0 auto;padding:var(--aha-space-96) var(--aha-space-64)}
.aha-features__header{max-width:720px;margin:0 0 var(--aha-space-64)}
.aha-features__header--center{margin-inline:auto;text-align:center}
.aha-features__eyebrow{
  margin:0 0 var(--aha-space-16);
  font-size:var(--aha-size-sm);
  font-weight:var(--aha-weight-semibold);
  letter-spacing:var(--aha-letter-spacing-subheadings);
  text-transform:uppercase;
  color:var(--aha-color-primary);
}
.aha-features__title{
  margin:0 0 var(--aha-space-20);
  font-family:var(--aha-font-display);
  font-size:var(--aha-size-h2);
  line-height:var(--aha-line-height-tight);
  font-weight:var(--aha-weight-semibold);
  letter-spacing:var(--aha-letter-spacing-headlines);
  color:var(--aha-text-default);
}
.aha-features__lead{
  max-width:44ch;
  font-size:clamp(var(--aha-size-l),1.4vw,var(--aha-size-xl));
  line-height:var(--aha-line-height-body);
  color:var(--aha-text-secondary);
}
.aha-features__header--center .aha-features__lead{margin-inline:auto}
.aha-features__stack{display:flex;flex-direction:column;align-items:flex-start;gap:var(--aha-space-12)}
.aha-features__icon{
  display:flex;align-items:center;justify-content:center;flex:none;
  width:var(--aha-space-48);height:var(--aha-space-48);
  border-radius:var(--aha-radius-default);
  background:var(--aha-bg-accent);color:var(--aha-color-primary);
}
.aha-features__item-title{
  font-size:var(--aha-size-xl);
  font-weight:var(--aha-weight-semibold);
  line-height:var(--aha-line-height-heading);
  color:var(--aha-text-default);
}
.aha-features__item-text{
  font-size:var(--aha-size-l);
  line-height:var(--aha-line-height-body);
  color:var(--aha-text-secondary);
}
.aha-features__list{display:flex;flex-direction:column;gap:var(--aha-space-32)}
.aha-features__list-item{display:flex;align-items:flex-start;gap:var(--aha-space-16)}
.aha-features__list-item .aha-features__stack{padding-top:var(--aha-space-12)}
.aha-features__more{
  display:inline-flex;align-items:center;gap:var(--aha-space-8);
  border-radius:var(--aha-radius-xs);
  font-size:var(--aha-size-default);
  font-weight:var(--aha-weight-semibold);
  color:var(--aha-text-default);
  text-decoration:none;
  transition:color var(--aha-motion-mid) var(--aha-ease-in-out);
}
.aha-features__more:hover{color:var(--aha-text-link-hover)}
.aha-features__more:focus-visible{outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-2)}
.aha-features__actions{display:flex;flex-wrap:wrap;gap:var(--aha-space-12);margin-top:var(--aha-space-16)}
.aha-features__button{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:var(--aha-space-8);
  height:var(--aha-control-height-button-xl);
  padding:0 var(--aha-space-28);
  border:1px solid var(--aha-button-primary-bg);
  border-radius:var(--aha-radius-lg);
  font-family:inherit;
  font-size:var(--aha-size-l);
  font-weight:var(--aha-weight-semibold);
  line-height:1;
  white-space:nowrap;
  text-decoration:none;
  cursor:pointer;
  background:var(--aha-button-primary-bg);
  color:var(--aha-button-primary-text);
  box-shadow:var(--aha-button-elevate-primary);
  transition-property:background,border-color,box-shadow,color;
  transition-duration:var(--aha-motion-mid);
  transition-timing-function:var(--aha-ease-in-out);
}
.aha-features__button:hover{background:var(--aha-button-primary-bg-hover);border-color:var(--aha-button-primary-bg-hover);box-shadow:var(--aha-button-elevate-primary-hover)}
.aha-features__button:active{background:var(--aha-button-primary-bg-press);border-color:var(--aha-button-primary-bg-press);box-shadow:var(--aha-button-elevate-primary)}
.aha-features__button:focus-visible{outline:none;box-shadow:0 0 0 var(--aha-space-2) var(--aha-bg-base),0 0 0 var(--aha-space-4) var(--aha-button-focus-ring)}
.aha-features__button--ghost{
  background:var(--aha-button-default-bg);
  color:var(--aha-button-default-text);
  border-color:var(--aha-button-default-border);
  box-shadow:var(--aha-button-elevate-secondary);
}
.aha-features__button--ghost:hover,.aha-features__button--ghost:active{background:var(--aha-button-default-bg);box-shadow:inset 0 0 0 100vmax var(--aha-button-default-bg-hover),var(--aha-button-elevate-secondary);border-color:var(--aha-button-default-border-hover);color:var(--aha-button-default-text-hover)}
.aha-features__button--ghost:active{border-color:var(--aha-button-default-border-press)}
.aha-features__button--ghost:focus-visible,.aha-features__button--ghost:focus-visible:is(:hover,:active){box-shadow:inset 0 0 0 100vmax var(--aha-button-default-bg-hover),0 0 0 var(--aha-space-2) var(--aha-bg-base),0 0 0 var(--aha-space-4) var(--aha-button-focus-ring)}
.aha-features__photo{
  display:flex;align-items:center;justify-content:center;
  width:100%;
  background:var(--aha-bg-container-secondary);
  border-radius:var(--aha-radius-marketing);
  color:var(--aha-icon-muted);
  overflow:hidden;
}
.aha-features__photo--4x3{aspect-ratio:4 / 3}
.aha-features__photo--16x9{aspect-ratio:16 / 9}
.aha-features__photo--3x4{aspect-ratio:3 / 4}
.aha-features__photo img{display:block;width:100%;height:100%;object-fit:cover}
.aha-features__checks{display:flex;flex-direction:column;gap:var(--aha-space-16);margin-top:var(--aha-space-16)}
.aha-features__checks li{display:flex;align-items:flex-start;gap:var(--aha-space-12);font-size:var(--aha-size-l);line-height:var(--aha-line-height-body);color:var(--aha-text-secondary)}
.aha-features__check{display:flex;align-items:center;justify-content:center;flex:none;width:var(--aha-space-24);height:var(--aha-space-24);border-radius:var(--aha-radius-pill);background:var(--aha-bg-accent);color:var(--aha-color-primary)}
@media (prefers-reduced-motion:reduce){
  .aha-features__button,.aha-features__more{transition:none}
}
@container aha-features (max-width:991px){
  .aha-features__title{font-size:var(--aha-size-h3)}
}
@container aha-features (max-width:767px){
  .aha-features__inner{padding:var(--aha-space-48) var(--aha-space-24)}
}
@container aha-features (max-width:479px){
  .aha-features__inner{padding:var(--aha-space-32) var(--aha-space-16)}
  .aha-features__title{font-size:var(--aha-size-h4)}
}

layouts.css:
.aha-features--alternating-screenshots .aha-features__rows{display:flex;flex-direction:column;gap:var(--aha-space-96)}
.aha-features--alternating-screenshots .aha-features__row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--aha-space-64);align-items:center}
.aha-features--alternating-screenshots .aha-features__row-title{
  font-family:var(--aha-font-display);
  font-size:var(--aha-size-h3);
  line-height:var(--aha-line-height-tight);
  font-weight:var(--aha-weight-semibold);
  letter-spacing:var(--aha-letter-spacing-headlines);
  color:var(--aha-text-default);
}
.aha-features--alternating-screenshots .aha-features__row-text{
  font-size:clamp(var(--aha-size-l),1.4vw,var(--aha-size-xl));
  line-height:var(--aha-line-height-body);
  color:var(--aha-text-secondary);
}
.aha-features--alternating-screenshots .aha-features__row:nth-child(even) .aha-features__visual{order:-1}
@container aha-features (max-width:991px){
  .aha-features--alternating-screenshots .aha-features__row{grid-template-columns:minmax(0,1fr);gap:var(--aha-space-32)}
  .aha-features--alternating-screenshots .aha-features__row:nth-child(even) .aha-features__visual{order:0}
  .aha-features--alternating-screenshots .aha-features__rows{gap:var(--aha-space-64)}
}
@container aha-features (max-width:479px){
  .aha-features--alternating-screenshots .aha-features__row-title{font-size:var(--aha-size-h4)}
}

.aha-features--alternating-photos .aha-features__rows{display:flex;flex-direction:column;gap:var(--aha-space-96)}
.aha-features--alternating-photos .aha-features__row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--aha-space-64);align-items:center}
.aha-features--alternating-photos .aha-features__row-title{
  font-family:var(--aha-font-display);
  font-size:var(--aha-size-h3);
  line-height:var(--aha-line-height-tight);
  font-weight:var(--aha-weight-semibold);
  letter-spacing:var(--aha-letter-spacing-headlines);
  color:var(--aha-text-default);
}
.aha-features--alternating-photos .aha-features__row-text{
  font-size:clamp(var(--aha-size-l),1.4vw,var(--aha-size-xl));
  line-height:var(--aha-line-height-body);
  color:var(--aha-text-secondary);
}
.aha-features--alternating-photos .aha-features__inner{padding-bottom:0}
.aha-features--alternating-photos .aha-features__bleed{padding-bottom:var(--aha-space-96)}
.aha-features--alternating-photos .aha-features__row{gap:0}
.aha-features--alternating-photos .aha-features__copy{padding-left:max(var(--aha-space-64),calc((100cqw - 1280px) / 2 + var(--aha-space-64)));padding-right:var(--aha-space-64)}
.aha-features--alternating-photos .aha-features__row:nth-child(even) .aha-features__copy{order:2;padding-left:var(--aha-space-64);padding-right:max(var(--aha-space-64),calc((100cqw - 1280px) / 2 + var(--aha-space-64)))}
.aha-features--alternating-photos .aha-features__photo{border-radius:0}
@container aha-features (max-width:991px){
  .aha-features--alternating-photos .aha-features__row{grid-template-columns:minmax(0,1fr);gap:var(--aha-space-32)}
  .aha-features--alternating-photos .aha-features__copy, .aha-features--alternating-photos .aha-features__row:nth-child(even) .aha-features__copy{order:0;padding:0 var(--aha-space-64)}
  .aha-features--alternating-photos .aha-features__rows{gap:var(--aha-space-64)}
}
@container aha-features (max-width:767px){
  .aha-features--alternating-photos .aha-features__inner{padding:var(--aha-space-48) var(--aha-space-24) 0}
  .aha-features--alternating-photos .aha-features__bleed{padding-bottom:var(--aha-space-48)}
  .aha-features--alternating-photos .aha-features__copy, .aha-features--alternating-photos .aha-features__row:nth-child(even) .aha-features__copy{padding:0 var(--aha-space-24)}
}
@container aha-features (max-width:479px){
  .aha-features--alternating-photos .aha-features__inner{padding:var(--aha-space-32) var(--aha-space-16) 0}
  .aha-features--alternating-photos .aha-features__bleed{padding-bottom:var(--aha-space-32)}
  .aha-features--alternating-photos .aha-features__copy, .aha-features--alternating-photos .aha-features__row:nth-child(even) .aha-features__copy{padding:0 var(--aha-space-16)}
  .aha-features--alternating-photos .aha-features__row-title{font-size:var(--aha-size-h4)}
}

.aha-features--icon-list-video .aha-features__band{background:var(--aha-vivid-pink-5)}
.aha-features--icon-list-video .aha-features__band .aha-features__inner{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--aha-space-64);padding-bottom:calc(var(--aha-space-96) * 2);align-items:start}
.aha-features--icon-list-video .aha-features__band .aha-features__header{margin:0}
.aha-features--icon-list-video .aha-features__overlap{max-width:1280px;margin:calc(var(--aha-space-96) * -1) auto 0;padding:0 var(--aha-space-64) var(--aha-space-96)}
.aha-features--icon-list-video .aha-features__frame{padding:var(--aha-space-12);border-radius:var(--aha-radius-xl);background:var(--aha-white)}
.aha-features--icon-list-video .aha-features__frame .aha-features__photo{border-radius:var(--aha-radius-lg)}
.aha-features--icon-list-video .aha-features__frame--video{max-width:960px;margin-inline:auto}
.aha-features--icon-list-video .aha-features__video{position:relative}
.aha-features--icon-list-video .aha-features__play{
  position:absolute;inset:0;margin:auto;
  display:flex;align-items:center;justify-content:center;
  width:var(--aha-space-64);height:var(--aha-space-64);
  padding:0;border:0;border-radius:var(--aha-radius-pill);
  background:var(--aha-button-primary-bg);color:var(--aha-button-primary-text);
  cursor:pointer;
  transition:background-color var(--aha-motion-mid) var(--aha-ease-in-out);
}
.aha-features--icon-list-video .aha-features__play:hover{background:var(--aha-button-primary-bg-hover)}
.aha-features--icon-list-video .aha-features__play:active{background:var(--aha-button-primary-bg-press)}
.aha-features--icon-list-video .aha-features__play:focus-visible{outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-2)}
@media (prefers-reduced-motion:reduce){
  .aha-features--icon-list-video .aha-features__play{transition:none}
}
@container aha-features (max-width:991px){
  .aha-features--icon-list-video .aha-features__band .aha-features__inner{grid-template-columns:minmax(0,1fr);gap:var(--aha-space-48)}
}
@container aha-features (max-width:767px){
  .aha-features--icon-list-video .aha-features__band .aha-features__inner{padding:var(--aha-space-48) var(--aha-space-24) calc(var(--aha-space-96) * 2)}
  .aha-features--icon-list-video .aha-features__overlap{padding:0 var(--aha-space-24) var(--aha-space-48)}
}
@container aha-features (max-width:479px){
  .aha-features--icon-list-video .aha-features__band .aha-features__inner{padding:var(--aha-space-32) var(--aha-space-16) calc(var(--aha-space-96) * 2)}
  .aha-features--icon-list-video .aha-features__overlap{padding:0 var(--aha-space-16) var(--aha-space-32)}
}

.aha-features--icon-list-wide-photo .aha-features__band{background:var(--aha-vivid-pink-5)}
.aha-features--icon-list-wide-photo .aha-features__band .aha-features__inner{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--aha-space-64);padding-bottom:calc(var(--aha-space-96) * 2);align-items:start}
.aha-features--icon-list-wide-photo .aha-features__band .aha-features__header{margin:0}
.aha-features--icon-list-wide-photo .aha-features__overlap{max-width:1280px;margin:calc(var(--aha-space-96) * -1) auto 0;padding:0 var(--aha-space-64) var(--aha-space-96)}
.aha-features--icon-list-wide-photo .aha-features__frame{padding:var(--aha-space-12);border-radius:var(--aha-radius-xl);background:var(--aha-white)}
.aha-features--icon-list-wide-photo .aha-features__frame .aha-features__photo{border-radius:var(--aha-radius-lg)}
.aha-features--icon-list-wide-photo .aha-features__frame--video{max-width:960px;margin-inline:auto}
.aha-features--icon-list-wide-photo .aha-features__video{position:relative}
.aha-features--icon-list-wide-photo .aha-features__play{
  position:absolute;inset:0;margin:auto;
  display:flex;align-items:center;justify-content:center;
  width:var(--aha-space-64);height:var(--aha-space-64);
  padding:0;border:0;border-radius:var(--aha-radius-pill);
  background:var(--aha-button-primary-bg);color:var(--aha-button-primary-text);
  cursor:pointer;
  transition:background-color var(--aha-motion-mid) var(--aha-ease-in-out);
}
.aha-features--icon-list-wide-photo .aha-features__play:hover{background:var(--aha-button-primary-bg-hover)}
.aha-features--icon-list-wide-photo .aha-features__play:active{background:var(--aha-button-primary-bg-press)}
.aha-features--icon-list-wide-photo .aha-features__play:focus-visible{outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-2)}
@media (prefers-reduced-motion:reduce){
  .aha-features--icon-list-wide-photo .aha-features__play{transition:none}
}
@container aha-features (max-width:991px){
  .aha-features--icon-list-wide-photo .aha-features__band .aha-features__inner{grid-template-columns:minmax(0,1fr);gap:var(--aha-space-48)}
}
@container aha-features (max-width:767px){
  .aha-features--icon-list-wide-photo .aha-features__band .aha-features__inner{padding:var(--aha-space-48) var(--aha-space-24) calc(var(--aha-space-96) * 2)}
  .aha-features--icon-list-wide-photo .aha-features__overlap{padding:0 var(--aha-space-24) var(--aha-space-48)}
}
@container aha-features (max-width:479px){
  .aha-features--icon-list-wide-photo .aha-features__band .aha-features__inner{padding:var(--aha-space-32) var(--aha-space-16) calc(var(--aha-space-96) * 2)}
  .aha-features--icon-list-wide-photo .aha-features__overlap{padding:0 var(--aha-space-16) var(--aha-space-32)}
}

.aha-features--tabs-screenshots .aha-features__tabs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--aha-space-64);align-items:center}
.aha-features--tabs-screenshots .aha-features__tablist{display:flex;flex-direction:column}
.aha-features--tabs-screenshots .aha-features__tab{
  display:flex;flex-direction:column;align-items:flex-start;gap:var(--aha-space-12);
  width:100%;
  padding:var(--aha-space-16) var(--aha-space-20);
  border:0;border-left:var(--aha-space-2) solid var(--aha-border-default);
  background:none;
  font-family:inherit;text-align:left;
  cursor:pointer;
  transition:border-color var(--aha-motion-mid) var(--aha-ease-in-out);
}
.aha-features--tabs-screenshots .aha-features__tab:hover{border-left-color:var(--aha-border-hover)}
.aha-features--tabs-screenshots .aha-features__tab[aria-selected="true"]{border-left-color:var(--aha-color-primary)}
.aha-features--tabs-screenshots .aha-features__tab:focus-visible{outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-2);border-radius:var(--aha-radius-xs)}
.aha-features--tabs-screenshots .aha-features__tabpanels{min-width:0}
@media (prefers-reduced-motion:reduce){
  .aha-features--tabs-screenshots .aha-features__tab{transition:none}
}
@container aha-features (max-width:991px){
  .aha-features--tabs-screenshots .aha-features__tabs{grid-template-columns:minmax(0,1fr)}
}
